Modelica source:
```modelica
connector Pin
  Real v;
  flow Real i;
end Pin;
model Ports0
  Pin in_n;
  Pin in_p;
  Pin out;
end Ports0;
model Ports1
  Pin n;
  Pin p;
end Ports1;
model Ports2
  Pin p;
end Ports2;
model Study
  Ports2 ground;
  Ports0 opAmp;
  Ports1 r1;
  Ports1 r2;
  Ports1 vIn;
  Ports1 vOut;
equation
  connect(ground.p, vIn.n);
  connect(ground.p, vOut.n);
  connect(opAmp.out, vOut.p);
  connect(opAmp.in_n, ground.p);
  connect(opAmp.out, r2.n);
  connect(r2.p, opAmp.in_p);
  connect(r2.p, r1.n);
  connect(r1.p, vIn.p);
end Study;
```

